  ["D1", "Daily Opening and Closing", "Operations", "", "Twice a year"],
  ["D2", "Payment, Refunds, and Reconciliation", "Operations", "", "Twice a year"],
  ["D3", "Inventory and Retail Management", "Operations", "", "Twice a year"],
