body.push(P("Your next step. Choose the four Phase 1 procedures, open the standard template, and write your first version of each this week using your own room setups, systems, and state requirements. A documented practice is not built in a day. It is built one procedure at a time, and it starts with the next one you write.", { before: 160, after: 60 }));

/* ===================== DOCUMENT ===================== */
const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: INK } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: INK }, paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: PLUM_DK }, paragraph: { spacing: { before: 260, after: 110 }, outlineLevel: 1 } }
    ]
  },
