{"language": "javascript", "code": "const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, HeadingLevel, BorderStyle,
  WidthType, ShadingType, VerticalAlign, PageNumber, TabStopType, TabStopPosition
} = require("docx");

/* ---------- palette ---------- */
const INK      = "2B2A2E"; // body charcoal
const PLUM     = "8E5A74"; // accent mauve
const PLUM_DK  = "5E3F50"; // deep plum (H2)
const HFILL    = "F1E9ED"; // table header fill
const ALTFILL  = "FAF6F8"; // alt row
const BORDERC  = "D8C7CF"; // soft border

/* ---------- numbering pool ---------- */
const numRefs = [];
const numConfig = [];
for (let i = 1; i <= 60; i++) {
  const ref = "num" + i;
  numRefs.push(ref);
  numConfig.push({
    reference: ref,
    levels: [{
      level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
      style: { paragraph: { indent: { left: 620, hanging: 320 } }, run: { font: "Arial", size: 22, color: INK } }
    }]
  });
}
numConfig.push({
  reference: "bullets",
  levels: [{
    level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 620, hanging: 320 } }, run: { font: "Arial", size: 22, color: INK } }
  }]
});
let numIdx = 0;
const nextNum = () => numRefs[numIdx++];

/* ---------- helpers ---------- */
const P = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after ?? 120, line: 276, ...(opts.before ? { before: opts.before } : {}) },
  alignment: opts.align,
  children: [new TextRun({ text, font: "Arial", size: opts.size ?? 22, color: opts.color ?? INK, italics: opts.italics, bold: opts.bold })]
});

const H1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 320, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: PLUM, space: 4 } },
  children: [new TextRun({ text, font: "Arial", size: 30, bold: true, color: INK })]
});

const H2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 260, after: 110 },
  children: [new TextRun({ text, font: "Arial", size: 24, bold: true, color: PLUM_DK })]
});

const H3 = (text) => new Paragraph({
  spacing: { before: 160, after: 80 },
  children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: PLUM_DK })]
});

const labeled = (label, text) => new Paragraph({
  spacing: { after: 110, line: 276 },
  children: [
    new TextRun({ text: label + "  ", font: "Arial", size: 22, bold: true, color: PLUM_DK }),
    new TextRun({ text, font: "Arial", size: 22, color: INK })
  ]
});

const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 70, line: 276 },
  children: [new TextRun({ text, font: "Arial", size: 22, color: INK })]
});

const numbered = (text, ref) => new Paragraph({
  numbering: { reference: ref, level: 0 },
  spacing: { after: 70, line: 276 },
  children: [new TextRun({ text, font: "Arial", size: 22, color: INK })]
});

const note = (text) => new Paragraph({
  spacing: { after: 140, line: 276 },
  border: { left: { style: BorderStyle.SINGLE, size: 16, color: PLUM, space: 8 } },
  indent: { left: 160 },
  children: [new TextRun({ text: "Note. ", font: "Arial", size: 21, bold: true, italics: true, color: PLUM_DK }),
             new TextRun({ text, font: "Arial", size: 21, italics: true, color: "555055" })]
});

/* ---------- table helpers ---------- */
const cell = (children, { w, fill, head = false, alt = false } = {}) => new TableCell({
  width: { size: w, type: WidthType.DXA },
  shading: { fill: head ? HFILL : (alt ? ALTFILL : "FFFFFF"), type: ShadingType.CLEAR },
  margins: { top: 70, bottom: 70, left: 130, right: 130 },
  verticalAlign: VerticalAlign.TOP,
  borders: {
    top:    { style: BorderStyle.SINGLE, size: 1, color: BORDERC },
    bottom: { style: BorderStyle.SINGLE, size: 1, color: BORDERC },
    left:   { style: BorderStyle.SINGLE, size: 1, color: BORDERC },
    right:  { style: BorderStyle.SINGLE, size: 1, color: BORDERC }
  },
  children: Array.isArray(children) ? children : [children]
});

const tcell = (text, opts = {}) => cell(
  new Paragraph({ spacing: { after: 0, line: 264 }, children: [
    new TextRun({ text, font: "Arial", size: opts.size ?? 20, bold: opts.head || opts.bold, color: opts.head ? PLUM_DK : INK })
  ] }),
  opts
);

/* ===================================================================== */
/* CONTENT                                                               */
/* ===================================================================== */
const body = [];

/* ----- Title block (no page break per brand rule) ----- */
body.push(new Paragraph({
  spacing: { after: 40 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 20, bold: true, color: PLUM, characterSpacing: 60 })]
}));
body.push(new Paragraph({
  spacing: { before: 80, after: 60 },
  children: [new TextRun({ text: "The Med Spa SOP Playbook", font: "Arial", size: 46, bold: true, color: INK })]
}));
body.push(new Paragraph({
  spacing: { after: 60 },
  children: [new TextRun({ text: "Building the Systems That Run Your Practice Without You", font: "Arial", size: 26, color: PLUM_DK, italics: true })]
}));
body.push(new Paragraph({
  spacing: { after: 200 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: PLUM, space: 6 } },
  children: [new TextRun({ text: "A course module for independent med spa owners", font: "Arial", size: 21, color: "6A6470" })]
}));

/* ----- Intro ----- */
body.push(P("A practice that depends on the owner being present is not a business yet. It is a job with extra stress. The difference between a med spa that the owner can step away from and one that falls apart the moment she leaves is almost never talent. It is documentation. The strongest practices write down how every important task is done, so the outcome is the same whether the owner is in the building or on a beach.", { after: 140 }));
body.push(P("This module gives you the standard operating procedures that every independent med spa needs, the templates to build each one, and the method to create, roll out, and maintain them with your team. Work through it in order. By the end you will have a documented practice that protects your clients, your license, and your time.", { after: 60 }));

/* ----- What this covers ----- */
body.push(H2("What This Playbook Covers"));
[
  "Part One. The Foundation. What an SOP is, the standard format every procedure should follow, and the method to write, roll out, and maintain them.",
  "Part Two. The Core SOP Library. Sixteen industry standard procedures across client experience, clinical and compliance, revenue, and operations, each with a ready to use template.",
  "Part Three. The Implementation Roadmap. The order to install your SOPs so your team is never overwhelmed.",
  "Part Four. The Master SOP Index. A single tracking system to keep your entire library current."
].forEach(t => body.push(bullet(t)));

/* ===================== PART ONE ===================== */
body.push(H1("Part One. The Foundation"));

body.push(H2("What a Standard Operating Procedure Is"));
body.push(P("A standard operating procedure, or SOP, is a written, repeatable instruction for how one specific task is performed in your practice. A good SOP is clear enough that a capable person who has never done the task can follow it and produce the same result your best team member would. That is the entire point. Consistency that does not depend on memory, mood, or who happens to be working that day.", { after: 120 }));
body.push(P("For a med spa, SOPs carry more weight than they do in most businesses, because four things are on the line at once.", { after: 80 }));
[
  "Safety and compliance. Clinical procedures, consent, privacy, and emergency response are not areas where improvisation is acceptable.",
  "Client experience. The premium feel that justifies your pricing comes from a consistent experience, not a lucky one.",
  "Speed of training. A documented practice turns a new hire into a contributor in weeks rather than months.",
  "Your freedom. Every task that lives only in your head is a task that keeps you chained to the building. Every task you document is a task you can hand off."
].forEach(t => body.push(bullet(t)));
body.push(P("Systems are not about control for its own sake. They are about making the owner more capable and the practice more independent. The goal is a business that runs on its standards, not on your presence.", { before: 60, after: 80 }));

body.push(H2("The Anatomy of a Strong SOP"));
body.push(P("Every SOP in your practice should follow one standard format. When the format is consistent, your team knows exactly where to look, and writing the next procedure becomes faster every time. Use the template below as the header and skeleton for every SOP you create.", { after: 120 }));

const anatomyRows = [
  ["Section", "What goes here"],
  ["Identification", "Title, SOP number, category, the owner responsible, version, date created, and date last reviewed."],
  ["Purpose", "One or two sentences on why this procedure exists and what it protects or produces."],
  ["Scope", "Who and what the procedure covers, and the moment it applies."],
  ["Responsibilities", "Who performs each part of the procedure."],
  ["Materials and tools", "Forms, products, equipment, or systems needed to complete the task."],
  ["Procedure", "Numbered steps in plain language, one action per step, in the order they happen."],
  ["Quality checks", "How anyone can confirm the task was done correctly."],
  ["References", "Linked forms, policies, consent documents, or clinical protocols."]
];
body.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [2400, 6960],
  rows: anatomyRows.map((r, i) => new TableRow({
    children: [
      tcell(r[0], { w: 2400, head: i === 0, bold: i !== 0, alt: i !== 0 && i % 2 === 0 }),
      tcell(r[1], { w: 6960, head: i === 0, alt: i !== 0 && i % 2 === 0 })
    ]
  }))
}));

body.push(H2("How to Write Any SOP From Scratch"));
body.push(P("You do not need a consultant to write a procedure. You need your best performer and an hour. Follow this method for any task in your practice.", { after: 100 }));
{
  const r = nextNum();
  [
    "Choose one task with a clear beginning and a clear end. Keep the scope small. One task, one SOP.",
    "Watch your best performer do the task and capture every step exactly as it happens.",
    "Write the steps in plain order, one action per step, with no assumed knowledge.",
    "Remove anything that depends on a single person's memory or judgment, and replace it with a written rule.",
    "Add the quality checks that prove the task was done correctly.",
    "Test the draft by having a different person follow it word for word without help.",
    "Fix whatever was unclear, then finalize, assign an owner, and set a review date."
  ].forEach(t => body.push(numbered(t, r)));
}
body.push(P("A simple test for what needs an SOP. If a task is performed more than once a week, affects client safety or money, or is known by only one person, it needs to be written down.", { before: 60, after: 60 }));

body.push(H2("How to Roll Out and Train Your Team"));
body.push(P("A library of perfect SOPs that no one uses changes nothing. Adoption is where most owners lose the value. Roll out with intention.", { after: 100 }));
{
  const r = nextNum();
  [
    "Store every SOP in one place that your whole team can reach from the floor.",
    "Introduce one procedure at a time. Releasing the full library at once guarantees that none of it sticks.",
    "Use the demonstrate, perform, sign off pattern. Show the procedure, watch the team member perform it, then record their sign off.",
    "Make the SOP the single source of truth. Coach to the document, not around it, so the standard does not drift.",
    "Build SOP sign off into onboarding so every new hire learns the standard from day one.",
    "Keep the most used procedures visible where the work actually happens."
  ].forEach(t => body.push(numbered(t, r)));
}

body.push(H2("How to Keep Your SOPs Alive"));
body.push(P("A procedure that is never reviewed becomes wrong over time, and a wrong SOP is worse than none, because your team follows it anyway. Maintenance is a system of its own.", { after: 100 }));
{
  const r = nextNum();
  [
    "Assign every SOP a single owner who is responsible for keeping it accurate.",
    "Review on a set cadence. Clinical and revenue procedures quarterly, operational procedures twice a year.",
    "Update the version number and the review date on every change, however small.",
    "Retire procedures that are no longer used so the library stays trustworthy.",
    "Track the entire library in one master index, covered in Part Four."
  ].forEach(t => body.push(numbered(t, r)));
}

/* ===================== PART TWO ===================== */
body.push(H1("Part Two. The Core SOP Library"));
body.push(P("These are the sixteen procedures that every independent med spa needs, grouped into four categories. Each one gives you the purpose, the moment it runs, a ready to use procedure you can drop straight into the standard template, and notes on how to implement and train it. Treat these as your starting drafts. Adjust the wording to your services, your systems, and your state requirements, then make them yours.", { after: 80 }));

const sops = [
  /* ----- A. CLIENT EXPERIENCE ----- */
  { cat: "Category A. Client Experience and Front of House" },
  {
    id: "A1", title: "Inbound Inquiry and Speed to Lead",
    purpose: "Convert every call, form, and message into a booked consultation quickly and consistently.",
    when: "Any new inquiry by phone, web form, direct message, text, or walk in.",
    steps: [
      "Acknowledge every inquiry within five minutes during business hours, and within thirty minutes after hours through an automated reply.",
      "Capture the name, phone, email, service interest, and how they found you in the CRM before anything else.",
      "Lead the conversation with a question about the client's goal, not the price.",
      "Offer two specific appointment times rather than asking when works for you.",
      "Book the consultation and send confirmation by text and email immediately.",
      "Tag the lead source and set a follow up task for any inquiry that does not book.",
      "If a call back goes unanswered, follow the three attempt rule across two channels within forty eight hours."
    ],
    implement: "Set CRM automations for instant replies, place a saved inquiry script at the front desk, and define your business hour and after hour response targets in writing.",
    train: "Role play five inbound scenarios and score each on speed, the goal question, and the two time slot offer. Review one recorded call per team member each week."
  },
  {
    id: "A2", title: "New Client Intake and Consultation",
    purpose: "Create a consistent, premium first visit that gathers complete medical information and sets the treatment relationship.",
    when: "Every first time client, before any treatment is performed.",
    steps: [
      "Send digital intake, medical history, and consent forms before arrival.",
      "Confirm the forms are complete and reviewed by the provider before the client is seated.",
      "Greet the client by name, offer water, and seat them in a private consultation room.",
      "Conduct a structured consultation covering concern, history, goals, timeline, and budget comfort.",
      "Take standardized before photos with signed photo consent.",
      "Present recommendations as a phased plan rather than a single service.",
      "Document everything in the chart and the CRM.",
      "Schedule the first treatment and the next step before the client leaves."
    ],
    implement: "Standardize the consultation room, the form stack, and the photo setup. Build a one page consultation guide that every provider follows.",
    train: "Have each provider shadow three consultations, then deliver one observed consultation scored against the guide."
  },
  {
    id: "A3", title: "Check Out and Rebooking",
    purpose: "Ensure that no client leaves without the next appointment booked and the visit fully closed.",
    when: "The end of every appointment.",
    steps: [
      "Walk the client to the front desk personally and hand off to reception by name with a one line summary of the visit.",
      "Reception confirms today's services and any home care or retail that was recommended.",
      "Book the next appointment before payment whenever it is clinically advised.",
      "Process payment, apply membership benefits, and offer retail tied to the treatment.",
      "Confirm the next visit by text and email.",
      "Set the post treatment follow up task according to protocol."
    ],
    implement: "Script the provider to front desk handoff and add a rebooking field that must be completed at checkout.",
    train: "Track rebooking rate by provider each week and coach anyone below target."
  },
  {
    id: "A4", title: "Appointment Confirmation, Reminders, Cancellations, and No Shows",
    purpose: "Protect the schedule and reduce the revenue lost to gaps and empty chairs.",
    when: "Continuously, around every booked appointment.",
    steps: [
      "Send a confirmation at booking, a reminder forty eight hours out, and a reminder two hours out.",
      "Require a confirmation reply, and flag any unconfirmed appointment for a personal call the day before.",
      "State the cancellation and deposit policy at booking and on every reminder.",
      "For cancellations inside the window, apply the policy consistently and offer the next available slot.",
      "For no shows, log the event, apply the policy, and trigger a reactivation sequence.",
      "Fill openings from a standby list."
    ],
    implement: "Set the reminder cadence in the CRM, publish a written cancellation policy, and build a standby list process.",
    train: "Teach the team to deliver the policy warmly and consistently, using three scripted responses."
  },

  /* ----- B. CLINICAL ----- */
  { cat: "Category B. Clinical, Compliance, and Safety" },
  {
    id: "B1", title: "Treatment Protocol and Pre and Post Care",
    purpose: "Deliver every service to the same clinical standard, with clear client preparation and aftercare.",
    when: "Every treatment, every time.",
    steps: [
      "Verify client identity, chart, allergies, and signed consent for today's service.",
      "Confirm the client followed pre care instructions, and reschedule if they are contraindicated.",
      "Set up the room and tray to the standard checklist for that service.",
      "Perform the service to the documented clinical protocol and dosing record.",
      "Document product, lot number, units or settings, and areas treated.",
      "Review written aftercare with the client and send a digital copy.",
      "Schedule the follow up or next session according to protocol."
    ],
    implement: "Build one protocol card per service that lists pre care, steps, settings, and aftercare. Track lot numbers in the chart.",
    train: "Certify each provider on each protocol before solo delivery, and re certify annually."
  },
  {
    id: "B2", title: "Sanitation, Infection Control, and Room Turnover",
    purpose: "Maintain a clean, compliant, and safe clinical environment between every client.",
    when: "Between every client, and at open and close.",
    steps: [
      "Remove and dispose of single use items, and place sharps in approved containers.",
      "Disinfect all surfaces, beds, and equipment with approved products and the required dwell time.",
