r1.push(H2("System 4. Make the Clinical Recommendation the Sale"));
r1.push(P("This is the heart of the program. In a med spa, retail is not sold, it is prescribed. The provider recommends homecare as a clinical part of the result, the same way a physician would recommend the medication that completes a treatment.", { after: 100 }));
[
  "End every treatment with a written homecare regimen tied to the result the client wants.",
  "Use outcome language. The result the client paid for depends in part on what they do at home. That is true, and it is the most honest and most effective frame there is.",
  "Let the provider prescribe and the front desk fulfill. This connects directly to your Check Out and Rebooking procedure, where the regimen is presented and rung up."
].forEach(t => r1.push(bullet(t)));
r1.push(H3("Homecare prescription template"));
r1.push(P("Give every provider a simple prescription to complete at the end of a treatment. It makes the recommendation routine and hands the front desk a ready order.", { after: 100 }));
