    return cell(paras, { w: widths[c], head: i === 0, alt: i !== 0 && i % 2 === 0 });
  }) })) }));

r1.push(H2("The Retail Scorecard"));
r1.push(P("Maintain one monthly scorecard so retail stays a managed number rather than an accident. Fill in your targets, then track the actuals each month.", { after: 120 }));
r1.push(simpleTable([
  ["Metric", "Target", "This month", "Last month", "Owner"],
  ["Retail as percent of revenue", "", "", "", ""],
  ["Retail attachment rate", "", "", "", ""],
  ["Average retail per visit", "", "", "", ""],
