{"language": "javascript", "code": "const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, HeadingLevel, BorderStyle,
  WidthType, ShadingType, VerticalAlign, PageNumber, TabStopType, TabStopPosition
} = require("docx");

/* ---------- palette ---------- */
const INK = "2B2A2E", PLUM = "8E5A74", PLUM_DK = "5E3F50",
      HFILL = "F1E9ED", ALTFILL = "FAF6F8", BORDERC = "D8C7CF";

/* ---------- numbering ---------- */
const numRefs = [], numConfig = [];
for (let i = 1; i <= 60; i++) {
  const ref = "num" + i; numRefs.push(ref);
  numConfig.push({ reference: ref, levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.",
    alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 620, hanging: 320 } }, run: { font: "Arial", size: 22, color: INK } } }] });
}
numConfig.push({ reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022",
  alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 620, hanging: 320 } }, run: { font: "Arial", size: 22, color: INK } } }] });
let numIdx = 0;
const nextNum = () => numRefs[numIdx++];

/* ---------- helpers ---------- */
const P = (text, opts = {}) => new Paragraph({ spacing: { after: opts.after ?? 120, line: 276, ...(opts.before ? { before: opts.before } : {}) },
  children: [new TextRun({ text, font: "Arial", size: opts.size ?? 22, color: opts.color ?? INK, italics: opts.italics, bold: opts.bold })] });
const H1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 160 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: PLUM, space: 4 } },
  children: [new TextRun({ text, font: "Arial", size: 30, bold: true, color: INK })] });
const H2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 260, after: 110 },
  children: [new TextRun({ text, font: "Arial", size: 24, bold: true, color: PLUM_DK })] });
const H3 = (text) => new Paragraph({ spacing: { before: 160, after: 80 },
  children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: PLUM_DK })] });
const labeled = (label, text) => new Paragraph({ spacing: { after: 110, line: 276 },
  children: [new TextRun({ text: label + "  ", font: "Arial", size: 22, bold: true, color: PLUM_DK }),
             new TextRun({ text, font: "Arial", size: 22, color: INK })] });
const bullet = (text) => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 70, line: 276 },
  children: [new TextRun({ text, font: "Arial", size: 22, color: INK })] });
const numbered = (text, ref) => new Paragraph({ numbering: { reference: ref, level: 0 }, spacing: { after: 70, line: 276 },
  children: [new TextRun({ text, font: "Arial", size: 22, color: INK })] });
const note = (text) => new Paragraph({ spacing: { after: 140, line: 276 },
  border: { left: { style: BorderStyle.SINGLE, size: 16, color: PLUM, space: 8 } }, indent: { left: 160 },
  children: [new TextRun({ text: "Note. ", font: "Arial", size: 21, bold: true, italics: true, color: PLUM_DK }),
             new TextRun({ text, font: "Arial", size: 21, italics: true, color: "555055" })] });

const cell = (children, { w, fill, head = false, alt = false } = {}) => new TableCell({
  width: { size: w, type: WidthType.DXA },
  shading: { fill: head ? HFILL : (alt ? ALTFILL : "FFFFFF"), type: ShadingType.CLEAR },
  margins: { top: 70, bottom: 70, left: 130, right: 130 }, verticalAlign: VerticalAlign.TOP,
  borders: { top: { style: BorderStyle.SINGLE, size: 1, color: BORDERC }, bottom: { style: BorderStyle.SINGLE, size: 1, color: BORDERC },
             left: { style: BorderStyle.SINGLE, size: 1, color: BORDERC }, right: { style: BorderStyle.SINGLE, size: 1, color: BORDERC } },
  children: Array.isArray(children) ? children : [children] });
const tcell = (text, opts = {}) => cell(new Paragraph({ spacing: { after: 0, line: 264 },
  children: [new TextRun({ text, font: "Arial", size: opts.size ?? 20, bold: opts.head || opts.bold, color: opts.head ? PLUM_DK : INK })] }), opts);

const simpleTable = (rows, widths) => new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: widths,
  rows: rows.map((r, i) => new TableRow({ children: r.map((txt, c) => tcell(txt, { w: widths[c], head: i === 0, bold: i !== 0 && c === 0, alt: i !== 0 && i % 2 === 0 })) })) });

const titleBlock = (kicker, title, subtitle, line) => ([
  new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: kicker, font: "Arial", size: 20, bold: true, color: PLUM, characterSpacing: 60 })] }),
  new Paragraph({ spacing: { before: 80, after: 60 }, children: [new TextRun({ text: title, font: "Arial", size: 46, bold: true, color: INK })] }),
  new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: subtitle, font: "Arial", size: 26, color: PLUM_DK, italics: true })] }),
  new Paragraph({ spacing: { after: 200 }, border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: PLUM, space: 6 } },
    children: [new TextRun({ text: line, font: "Arial", size: 21, color: "6A6470" })] })
]);

const buildDoc = (shortTitle, body, outPath) => {
  const doc = new Document({
    styles: { default: { document: { run: { font: "Arial", size: 22, color: INK } } },
      paragraphStyles: [
