c.push(tableFrom([
  ["Component", "Amount"],
  ["Base, 160 hours at $24", "$3,840"],
  ["Service commission, 10 percent of $11,900 net production", "$1,190"],
  ["Retail commission, 12 percent of $2,500 prescribed", "$300"],
  ["Total for the month", "$5,330"]
], [6360, 3000]));
c.push(H3("Front desk and manager"));
["Front desk is hourly, plus a team bonus pool, for example six hundred dollars split among the team in a month the practice hits its rebooking and review targets, with an optional twenty five dollars per membership a coordinator personally enrolls.","Manager is salaried, with a quarterly bonus, for example up to two thousand dollars when the labor cost ratio, retention, and revenue targets are all met."].forEach(t => c.push(bullet(t)));

/* ---- Part Five: PUTTING IT INTO MOTION ---- */
c.push(H1("Part Five. Putting It Into Motion"));
c.push(H2("The Rollout, Step by Step"));
{
  const n = nextNum();
  [
